<?php require __DIR__.'/common.php';$u=monitor_user();if(!monitor_admin($u)){http_response_code(403);head('Pracownicy');echo '<div class="alert alert-warning">Ta funkcja jest dostępna dla administratora.</div>';foot();exit;}$d=db();$message='';if(($_SERVER['REQUEST_METHOD']??'')==='POST'){monitor_post();try{if(posted('action')==='worker'){$id=(int)posted('worker');$enabled=posted('enabled')==='1'?1:0;$s=$d->prepare("UPDATE z6_users SET worker=? WHERE id=? AND username<>'admin'");$s->bind_param('ii',$enabled,$id);$s->execute();$message='Zmieniono uprawnienie pracownika.';}else{[$host,$port]=monitor_target(posted('host'),(int)posted('port'));$id=(int)posted('worker');$s=$d->prepare('INSERT INTO z6_domeny(host,port,user_id) SELECT ?,?,id FROM z6_users WHERE id=? AND worker=1');$s->bind_param('sii',$host,$port,$id);$s->execute();$message=$s->affected_rows?'Przydzielono usługę pracownikowi.':'Wybierz aktywnego pracownika.';}}catch(Throwable $e){$message=$e instanceof InvalidArgumentException?$e->getMessage():'Nie udało się zapisać; sprawdź, czy usługa już istnieje.';}}
$users=$d->query("SELECT id,username,worker FROM z6_users WHERE username<>'admin' ORDER BY username")->fetch_all(MYSQLI_ASSOC);$d->close();head('Pracownicy i przydziały usług');if($message)echo '<div class="alert alert-info">'.h($message).'</div>';echo '<form class="card p-4 mb-4" method="post"><input type="hidden" name="csrf" value="'.h(monitor_csrf()).'"><input type="hidden" name="action" value="assign"><label class="form-label" for="host">Host</label><input class="form-control mb-2" name="host" id="host" required maxlength="190"><label class="form-label" for="port">Port</label><input class="form-control mb-2" name="port" id="port" type="number" min="1" max="65535" value="443" required><label class="form-label" for="worker">Odpowiedzialny pracownik</label><select class="form-select mb-3" name="worker" id="worker">';foreach($users as $r)if($r['worker'])echo '<option value="'.(int)$r['id'].'">'.h($r['username']).'</option>';echo '</select><button class="btn btn-primary">Przydziel usługę</button></form><h2 class="h4">Status pracowników</h2>';foreach($users as $r)echo '<form class="d-flex gap-2 align-items-center mb-2" method="post"><input type="hidden" name="csrf" value="'.h(monitor_csrf()).'"><input type="hidden" name="action" value="worker"><input type="hidden" name="worker" value="'.(int)$r['id'].'"><span>'.h($r['username']).'</span><select name="enabled" class="form-select w-auto"><option value="0">Zwykły użytkownik</option><option value="1" '.($r['worker']?'selected':'').'>Pracownik</option></select><button class="btn btn-outline-light">Zapisz</button></form>';foot();
